import{_ as e,a,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const h=JSON.parse('{"title":"Catalog Product — Copy","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-catalog-product-copy","title":"Copy a Catalog Product","description":"Duplicates an existing product across all sub-resources. Refuses configurable variants.","query":"mutation CopyProduct($input: createAdminCatalogProductCopyInput!) {\\n  createAdminCatalogProductCopy(input: $input) {\\n    adminCatalogProductCopy { id sourceId sku type name success message }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": { \\"sourceId\\": 12 }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminCatalogProductCopy\\": {\\n      \\"adminCatalogProductCopy\\": {\\n        \\"_id\\": 43,\\n        \\"sourceId\\": 12,\\n        \\"sku\\": \\"temporary-sku-c90a67\\",\\n        \\"type\\": \\"simple\\",\\n        \\"name\\": \\"Copy Of Classic Watch\\",\\n        \\"success\\": true,\\n        \\"message\\": \\"Product copied successfully.\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/catalog/products/copy.md","filePath":"api/graphql-api/admin/catalog/products/copy.md","lastUpdated":1787725411000}'),r={name:"api/graphql-api/admin/catalog/products/copy.md"};function c(i,t,n,s,p,l){return o(),a("div",null,t[0]||(t[0]=[d('<h1 id="catalog-product-—-copy" tabindex="-1">Catalog Product — Copy <a class="header-anchor" href="#catalog-product-—-copy" aria-label="Permalink to &quot;Catalog Product — Copy&quot;">​</a></h1><p>Equivalent to <a href="/api/rest-api/admin/catalog/products/copy.html"><code>POST /api/admin/catalog/products/{sourceId}/copy</code></a>.</p><p>The example uses an illustrative id. Replace it with a product that exists in your store — <a href="/api/graphql-api/admin/catalog/products.html"><code>adminCatalogProducts</code></a> lists valid ids.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>createAdminCatalogProductCopy</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>sourceId</code></td><td>Int</td><td>Yes</td><td>Id of the product to duplicate.</td></tr></tbody></table><h2 id="payload-fields" tabindex="-1">Payload Fields <a class="header-anchor" href="#payload-fields" aria-label="Permalink to &quot;Payload Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>_id</code></td><td>Int</td><td>Id of the newly created copy.</td></tr><tr><td><code>sourceId</code></td><td>Int</td><td>Id of the product that was copied.</td></tr><tr><td><code>sku</code></td><td>String</td><td>Generated SKU, always <code>temporary-sku-&lt;hex&gt;</code> — it does not derive from the source SKU.</td></tr><tr><td><code>type</code></td><td>String</td><td>Product type, matching the source.</td></tr><tr><td><code>name</code></td><td>String</td><td>Source name prefixed with <code>Copy Of </code>.</td></tr><tr><td><code>success</code></td><td>Boolean</td><td>Always <code>true</code> on success.</td></tr><tr><td><code>message</code></td><td>String</td><td>Translated confirmation.</td></tr></tbody></table><p>Select <code>_id</code>, not <code>id</code>. This is an action result with no route of its own, so its <code>id</code> resolves to <code>/api/admin/admin_catalog_product_copies/&lt;id&gt;</code>, which is not a queryable path.</p><h2 id="what-gets-copied" tabindex="-1">What Gets Copied <a class="header-anchor" href="#what-gets-copied" aria-label="Permalink to &quot;What Gets Copied&quot;">​</a></h2><p>Attribute values, images, categories, inventories, and customer-group prices all carry over, as do the type-specific structures — a configurable&#39;s variants, a bundle&#39;s options, a grouped product&#39;s links.</p><p>Two things do not: the SKU and URL key are regenerated, and the copy is created <strong>disabled</strong> (<code>status: &quot;0&quot;</code>) with a <code>null</code> <code>urlKey</code>, so it is never live by accident. Give it a real SKU, name, and URL key through <a href="/api/graphql-api/admin/catalog/products/update.html">Update</a> before enabling it.</p><p>The payload is a summary, not a product — re-query <a href="/api/graphql-api/admin/catalog/products/products-detail.html"><code>adminCatalogProduct</code></a> with the returned <code>_id</code> to read the copy.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p>Passing a configurable <strong>variant</strong> id fails with <code>Variants of configurable products cannot be copied. Copy the parent configurable product instead.</code> in <code>errors[]</code>. Copying the parent brings its variants along, which is what you want in nearly every case.</p><p>An unknown <code>sourceId</code> returns a not-found message in <code>errors[]</code>; a token without <code>catalog.products.create</code> returns <code>You do not have permission to manage products.</code></p>',17)]))}const g=e(r,[["render",c]]);export{h as __pageData,g as default};
